use super::*;
fn f(bits:u32)->f32 {f32::from_bits(bits)}
fn v2(b:[u32;2])->Vec2 {Vec2::new(f(b[0]),f(b[1]))}
fn v3(b:[u32;3])->Vec3 {Vec3::new(f(b[0]),f(b[1]),f(b[2]))}
