#[test]fn original_b_curve_errors(){
assert_eq!(Curve2::try_new(vec![],false).unwrap_err(),CurveError::TooFewPoints(0));
assert_eq!(Curve2::try_new(vec![v2([0,0])],false).unwrap_err(),CurveError::TooFewPoints(1));
assert_eq!(Curve2::try_new(vec![v2([0,0]),v2([0,0])],false).unwrap_err(),CurveError::NonFiniteLength);
assert_eq!(Curve2::try_new(vec![v2([0,0]),v2([0,0]),v2([1065353216,0])],true).unwrap_err(),CurveError::DuplicateSegment(0));
assert_eq!(Curve2::try_new(vec![v2([0,0]),v2([1065353216,0]),v2([1065353216,0])],true).unwrap_err(),CurveError::DuplicateSegment(1));
assert_eq!(Curve2::try_new(vec![v2([0,0]),v2([2143289344,0])],false).unwrap_err(),CurveError::NonFiniteLength);
assert_eq!(Curve2::try_new(vec![v2([0,0]),v2([2139095040,0])],false).unwrap_err(),CurveError::NonFiniteLength);
}
